  ('video-ia-avatar', 'Formation', $j${"sessions":[{"texte":"18-19 janvier 2027","debut":"2027-01-18","fin":"2027-01-19"},{"texte":"14-15 juin 2027","debut":"2027-06-14","fin":"2027-06-15"}],"tarif":890,"tarifParcours":850,"positionnement":"Questionnaire de positionnement IA générative niveau 2","positionnementLien":"https://forms.cloud.microsoft/Pages/ResponsePage.aspx?id=Hz0Qv17q6UGnq4TPIjn3VuJ6PqaOIbBNo7yikl5HEwdUMFg2MDlIMzM0NzROQVhGT1hSMzVNWkVGMS4u","cpf":"Oui, dans un parcours de 4 jours minimum"}$j$::jsonb),
  ('web-wordpress', 'Formation', $j${"sessions":[{"texte":"25-26 mars, 1er et 2 avril 2027","debut":"2027-03-25","fin":"2027-04-02"}],"tarif":1520,"positionnement":"Questionnaire de positionnement WordPress","positionnementLien":"https://forms.cloud.microsoft/Pages/ShareFormPage.aspx?id=Hz0Qv17q6UGnq4TPIjn3VuJ6PqaOIbBNo7yikl5HEwdURUtJUUFHMVVYRlpETlU4SUtTTUpFTzA5Si4u&sharetoken=uV8G8J7W6ZO7B0iI4Quj","cpf":"Oui (certification Tosa)"}$j$::jsonb),
  ('web-geo-seo', 'Formation', $j${"sessions":[{"texte":"2 et 16 avril 2027","debut":"2027-04-02","fin":"2027-04-16"},{"texte":"5 et 12 octobre 2027","debut":"2027-10-05","fin":"2027-10-12"}],"tarif":780,"tarifParcours":700,"cpf":"Oui, dans un parcours de 4 jours minimum"}$j$::jsonb)
),
nouveaux as (
  select f.id, jsonb_agg(case when p.patch is null then m else m || p.patch end order by o) as modules
  from public.formations f
  cross join lateral jsonb_array_elements(f.data->'modules') with ordinality as t(m, o)
  left join p on p.fid = f.id and p.code = m->>'code'
  where f.id in (select fid from p)
  group by f.id
)
update public.formations f set data = jsonb_set(f.data, '{modules}', nouveaux.modules), updated_at = now()
from nouveaux where f.id = nouveaux.id;

